import asyncio

async def main():
    r = await yuki_workspace_read({"path": "/workspace/start.txt"})
    ptr = r['data']['text'].strip()
    path = ptr
    visited = []
    total = 0
    guard = 0
    while True:
        guard += 1
        if guard > 1000:
            return "LOOP_GUARD"
        rr = await yuki_workspace_read({"path": "/workspace/" + path})
        if not rr['ok']:
            return "READ_FAIL " + path + " " + str(rr.get('error'))
        txt = rr['data']['text']
        d = {}
        for ln in txt.splitlines():
            ln = ln.strip()
            if not ln:
                continue
            if '=' in ln:
                k, v = ln.split('=', 1)
                d[k.strip()] = v.strip()
        value = int(d['value'])
        visited.append((path, value))
        total += value
        nxt = d.get('left') if value % 2 == 0 else d.get('right')
        if nxt is None:
            return "NO_NEXT " + str(d)
        nxt = nxt.strip()
        if nxt == 'END':
            break
        path = nxt
    return {"visited": visited, "total": total, "n": len(visited)}

